// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2, ERC20} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;

    function setUp() public { c = new PuttyV2("", 0, address(this)); }

    function testFuzz_property(
        bool isCall,
        bool isLong,
        uint256 duration,
        uint256 expiration,
        uint256 warpTime
    ) public {
        vm.assume(isLong || isCall); // keep both branches reachable, avoid put-short strike path complexity
        duration = bound(duration, 1, 10_000 days - 1);
        warpTime = bound(warpTime, 1_000_000, 2_000_000_000);
        vm.warp(warpTime);
        expiration = bound(expiration, warpTime + 1, type(uint128).max);

        // adversarial counterparties: an ERC1271 signer (the order maker) and a
        // minimal ERC20 base asset that accepts transferFrom/transfer
        ERC1271Maker maker = new ERC1271Maker();
        FakeERC20 base = new FakeERC20();

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: isCall,
            isLong: isLong,
            baseAsset: address(base),
            strike: 0,
            premium: 0,
            duration: duration,
            expiration: expiration,
            nonce: 0,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes memory sig = new bytes(65);
        uint256[] memory floorIds = new uint256[](0);

        vm.prank(address(0xB0B));
        c.fillOrder(order, sig, floorIds);

        uint256 key = isLong
            ? uint256(c.hashOrder(order))
            : uint256(c.hashOppositeOrder(order));

        // General rule: every successfully filled order records an expiration of
        // block.timestamp + order.duration at the long-position hash.
        assertTrue(c.positionExpirations(key) == warpTime + duration);
    }
}

contract ERC1271Maker {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return this.isValidSignature.selector;
    }
}

